// Reader
func GetBalance(ctx context.Context, acct string) (int64, error) {
    key := "bal:" + acct
    v, err := rdb.Get(ctx, key).Int64()
    if err == nil {
        return v, nil
    }
    bal, err := db.ReadBalance(ctx, acct)   // T1: reads old balance
    if err != nil {
        return 0, err
    }
    rdb.Set(ctx, key, bal, 0)               // T4: writes the OLD value back
    return bal, nil
}

// Writer
func SetBalance(ctx context.Context, acct string, bal int64) error {
    if err := db.WriteBalance(ctx, acct, bal); err != nil {   // T2
        return err
    }
    rdb.Del(ctx, "bal:"+acct)                                 // T3
    return nil
}
